// Reset clears every field of m, the fields that the encoding leaves out
// included. An encoded pointer or interface becomes nil. An encoded slice or
// map becomes empty and keeps its storage for a decode to reuse, with every
// element in the capacity of a slice reset, so that no decoded data stays
// reachable through m.
func (m *Appenders) Reset() {
	if m == nil {
		return
	}
	m.Token = 0
	m.Grade = 0
	m.Stamp = Stamp{}
	m.Note = ""
	m.Seal = Seal{}
	m.Hash = Hash{}
	m.Clip = ""
}

// CloneKanon returns a copy of m that shares no memory with m or with the slab
// that m decoded from: its strings, slices, maps and the values of its pointers
// and interfaces are copies. The copy has the fields of the encoding, the union
// discriminators and the unknown fields of m, and the zero value in every other
// field, map keys included. A nil m returns nil.
func (m *Appenders) CloneKanon() *Appenders {
	if m == nil {
		return nil
	}
	c := new(Appenders)
	m.cloneKanon(c)
	return c
}

// cloneKanon copies m into c, as CloneKanon does. The fields of c that the copy
// does not set keep their values. CloneKanon and the clone of the structs of
// the package that contain Appenders call it.
func (m *Appenders) cloneKanon(c *Appenders) {
	c.Token = m.Token
	c.Grade = m.Grade
	c.Stamp = m.Stamp
	_codecs_cloneNote(&c.Note, &m.Note)
	c.Seal = m.Seal
	c.Hash = m.Hash
	_codecs_cloneClip(&c.Clip, &m.Clip)
}

// _codecs_sizeToken returns the length of the encoding of the Token that x
// points at, and 1 when x fails to encode itself, so that the value is present
// and its encode reports the failure.
func _codecs_sizeToken(x *Token) int {
	var scratch [128]byte
	enc, err := x.AppendBinary(scratch[:0])
	if err != nil {
		return 1
	}
	return len(enc)
}

