// _codecs_putClip writes the encoding of the Clip that x points at into the end
// of buf, which has room for it, and returns its length. The room is the length
// that the SizeKanon of x returns. It fails when x fails to encode itself, and
// when its encoding has another length.
func _codecs_putClip(buf []byte, x *Clip, loc string, num int) (int, error) {
	n := x.SizeKanon()
	if uint(n) > uint(len(buf)) {
		return 0, wire.SizeError(loc, num)
	}
	i := len(buf) - n
	enc, err := x.AppendText(buf[i:i:len(buf)])
	if err != nil {
		return 0, wire.MarshalError(err, loc, num)
	}
	if len(enc) != n {
		return 0, wire.SizeError(loc, num)
	}
	return n, nil
}

