// _codecs_cloneWord copies the Word that src points at into dst through its
// encode and decode methods, and by assignment when they fail.
func _codecs_cloneWord(dst, src *Word) {
	*dst = *src
	enc, err := src.MarshalText()
	if err != nil {
		return
	}
	var c Word
	if c.UnmarshalText(enc) == nil {
		*dst = c
	}
}

